import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

/**
 * Directory where wiki markdown pages are stored.
 */
export const WIKI_PAGES_DIR = "/home/user/qwik-app/wiki-pages";

/**
 * Sanitizes a slug so it can't be used to escape the wiki-pages directory.
 */
function sanitizeSlug(slug: string): string {
  return slug.replace(/[\\/]/g, "").replace(/\.\./g, "");
}

export function getWikiFilePath(slug: string): string {
  const safeSlug = sanitizeSlug(slug);
  return join(WIKI_PAGES_DIR, `${safeSlug}.md`);
}

export function wikiPageExists(slug: string): boolean {
  return existsSync(getWikiFilePath(slug));
}

export function readWikiPage(slug: string): string {
  return readFileSync(getWikiFilePath(slug), "utf-8");
}

export function writeWikiPage(slug: string, content: string): void {
  if (!existsSync(WIKI_PAGES_DIR)) {
    mkdirSync(WIKI_PAGES_DIR, { recursive: true });
  }
  writeFileSync(getWikiFilePath(slug), content, "utf-8");
}

import { DatabaseSync } from "node:sqlite";
import { existsSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";

/**
 * Path to the local SQLite database used to store wiki revision history.
 */
export const WIKI_DB_PATH = "/home/user/qwik-app/wiki.db";

export interface Revision {
  id: number;
  slug: string;
  user: string;
  timestamp: number;
  content_length: number;
}

let dbInstance: DatabaseSync | undefined;

function getDb(): DatabaseSync {
  if (!dbInstance) {
    const dir = dirname(WIKI_DB_PATH);
    if (!existsSync(dir)) {
      mkdirSync(dir, { recursive: true });
    }

    dbInstance = new DatabaseSync(WIKI_DB_PATH);
    dbInstance.exec(`
      CREATE TABLE IF NOT EXISTS revisions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        slug TEXT NOT NULL,
        user TEXT NOT NULL,
        timestamp INTEGER NOT NULL,
        content_length INTEGER NOT NULL
      )
    `);
  }
  return dbInstance;
}

export function insertRevision(
  slug: string,
  user: string,
  contentLength: number,
): Revision {
  const db = getDb();
  const timestamp = Date.now();

  const stmt = db.prepare(
    "INSERT INTO revisions (slug, user, timestamp, content_length) VALUES (?, ?, ?, ?)",
  );
  const result = stmt.run(slug, user, timestamp, contentLength);

  return {
    id: Number(result.lastInsertRowid),
    slug,
    user,
    timestamp,
    content_length: contentLength,
  };
}

export function getRevisions(slug: string): Revision[] {
  const db = getDb();
  const stmt = db.prepare(
    "SELECT id, slug, user, timestamp, content_length FROM revisions WHERE slug = ? ORDER BY timestamp DESC",
  );
  const rows = stmt.all(slug) as unknown as Revision[];
  return rows;
}

import type { RequestHandler } from "@builder.io/qwik-city";
import { micromark } from "micromark";
import { readWikiPage, wikiPageExists } from "~/lib/wiki-fs";

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function renderPage(title: string, bodyHtml: string): string {
  return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <title>${escapeHtml(title)}</title>
  </head>
  <body>
    <div class="wiki-content">${bodyHtml}</div>
  </body>
</html>`;
}

export const onGet: RequestHandler = async (requestEvent) => {
  const { slug } = requestEvent.params;

  if (!slug || !wikiPageExists(slug)) {
    requestEvent.html(
      404,
      renderPage(
        "Page not found",
        `<p>The wiki page "${escapeHtml(slug ?? "")}" does not exist.</p>`,
      ),
    );
    return;
  }

  const markdown = readWikiPage(slug);
  const contentHtml = micromark(markdown);

  requestEvent.html(200, renderPage(slug, contentHtml));
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { writeWikiPage } from "~/lib/wiki-fs";
import { insertRevision } from "~/lib/wiki-db";

interface EditPayload {
  content?: unknown;
  user?: unknown;
}

export const onPost: RequestHandler = async (requestEvent) => {
  const { slug } = requestEvent.params;

  if (!slug) {
    requestEvent.json(400, { success: false, error: "Missing slug" });
    return;
  }

  const contentType = requestEvent.request.headers.get("content-type") ?? "";
  const isJsonRequest = contentType.includes("application/json");

  let payload: EditPayload | null = null;
  try {
    payload = (await requestEvent.parseBody()) as EditPayload | null;
  } catch {
    payload = null;
  }

  const content = typeof payload?.content === "string" ? payload.content : "";
  const user = typeof payload?.user === "string" ? payload.user : "";

  writeWikiPage(slug, content);
  insertRevision(slug, user, content.length);

  if (isJsonRequest) {
    requestEvent.json(200, { success: true });
    return;
  }

  throw requestEvent.redirect(303, `/wiki/${slug}`);
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { getRevisions } from "~/lib/wiki-db";

export const onGet: RequestHandler = async (requestEvent) => {
  const { slug } = requestEvent.params;

  if (!slug) {
    requestEvent.json(400, { success: false, error: "Missing slug" });
    return;
  }

  const revisions = getRevisions(slug);

  requestEvent.json(200, revisions);
};

